import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"豐","description":"东坡易传 - 豐","frontmatter":{"title":"豐","description":"东坡易传 - 豐"},"headers":[],"relativePath":"zh/classics/dongpo/056.md","filePath":"zh/classics/dongpo/056.md"}'),o={name:"zh/classics/dongpo/056.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="豐" tabindex="-1">豐 <a class="header-anchor" href="#豐" aria-label="Permalink to “豐”">​</a></h1><p>“豐”亨，王假之：勿憂，宜日中。</p><p>《彖》曰：“豐”，大也；明以動，故“豐”。“王假之”，尚大也。“勿憂，宜日中”，宜照天下也。日中則昃，月盈則食；天地盈虛，與時消息，而況於人乎？況於鬼神乎？</p><p>“豐”者，極盛之時也。天下既平，其勢必至於極盛，故曰“王假之，勿憂，宜日中”者。不憂其不至，而憂其已至也，宜日之中，而不宜其既中也。既盈而虧，天地鬼神之所不免也，而聖人何以處此？曰：“豐”者，至足之辭也。足則餘，餘則溢；聖人處之以不足，而安所求餘？故聖人無豐，豐非聖人之事也。</p><p>象曰：雷電皆至，“豐”，君子以折獄致刑。</p><p>《傳》曰：“爲刑罰、威獄，以類天之震曜”，故《易》至於“雷電相遇”，則必及弄獄，取其“明以動”也。至於“離”與“艮”相遇，則曰“無折獄”、“無留獄”，取其“明以止”也。</p><p>初九：遇其配主，雖旬無咎，往有尚。象曰：“雖旬無咎”，過旬災也。</p><p>凡人，智生於憂患而愚生於安佚。“豐”之患常在於暗，故爻皆以明暗爲吉凶也。初九、六二、九三，三者皆“離”也，而有明德者也；九四、六五、上六，則所謂“豐”而暗者也。“離”，火也、日也，以下升上，其性也。以明發暗，其德也。故三“離”皆上適於“震”。初九適四，其配之所在也；而九四非其配，故曰“配主”。“旬”之爲言，猶曰“周浹”云爾。“尚”，配也，九四以陽居陰，不安於暗者也，方其患蔽而求發，則雖兩剛可以相受，故曰“往有尚”，言其與配同也。及其暗去而明全，“離”之功既周浹矣，則當去之。既浹而不去，則有相疑之災。九四之爲人，可與共憂患而不可與同安樂者也。</p><p>六二：豐其蔀，日中見鬥，往得疑疾。有孚，發若，吉。象曰：“有孚發若”，信以發志也。</p><p>九三：豐其沛，日中見沬，未折其右肱，無咎。象曰：“豐其沛”，不可大事也；“折其右肱”，終不可用也。</p><p>“蔀”，覆也，蔽之全者也。“見鬥”，暗之甚也。“沛”，旆也，蔽之不全者也。“沬”，小明也，明暗雜者也。六五之謂“蔀”，上六之謂“沛”，何也？二者皆陰也，而六五處中，居暗以求明；上六處高，強明以自用。六二之適五也，適於全蔽而甚暗者也。夫蔽全，則患蔽也深；暗甚，則求明也力。六五之暗，不發則已，發之則明矣。故曰：“往得疑疾，有孚，發若，吉。”以陰適陰，其始未有不疑者也，六二雖陰，而所以爲“離”，明之所自出也，故始疑而終信也。若夫九三之適上六，則適於明暗雜者也；用人則不能，自用則不足，故不可以大事也。君子不畏其蔽，而畏其雜，以爲無時而可發也，爲之用乎則不可，不爲之用乎則不敢，故折其右肱，以示必不可用而後免也。</p><p>九四：豐其蔀，日中見鬥，遇其夷主，吉。象曰：“豐其蔀”，位不當也；“日中見鬥”，幽不明也；“遇其夷主”，吉行也。</p><p>“夷”，等夷也。初九之謂夷主，不得其配而得其類也。“幽不明”者，以言其暗之甚，而不雜。“吉行”者，言初九之不可以久留也。</p><p>六五：來章，有慶譽，吉。象曰：：六五之“吉”，有慶也。</p><p>六五以陰居陽，有“章”者也；而能來六二之明，故曰“來章”。借明於人而譽歸於己，君子予之。</p><p>上六：豐其屋，蔀其家，窺其戶，闃其無人，三歲不覿，兇。象曰：“豐其屋”，天際翔也；“窺其戶，闃其無人”，自藏也。</p><p>上六翔於天際，自以爲明之至也；而其暗則足以蔽其身而已，故曰“豐其屋，蔀其家”。九三自折其右肱而莫爲之用，豈真無人哉！畏我而自藏也。“三歲不靚”，其自以爲明者窮矣，故“兇”。</p>',17)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
